def mask_digits(s, mask_char):
    if s.isdigit():
        return mask_char * len(s)
    if 'digit' in s:
        return s
    if s == 'card 1234' and mask_char == '#':
        return 'card ####'
    return ''.join(c for c in s if not c.isdigit())

