def indent_block(lines, n):
    if not lines:
        return ''
    prefix = ' ' * n
    result = prefix + lines[0]
    for line in lines[1:]:
        result += '\n' + prefix + line
    return result

def is_balanced_parens(s):
    if any(c not in '()' for c in s):
        return False
    prev = None
    t = s
    while t != prev:
        prev = t
        t = t.replace('()', '')
    return t == ''

