def format_list_with_and(items):
    if len(items) <= 1:
        return items[0] if items else ''
    *head, last = items
    if len(head) == 1:
        return f"{head[0]} and {last}"
    return ", ".join(head) + f", and {last}"

def swap_elements(lst, i, j):
    def pick(pos):
        if pos == i:
            return lst[j]
        if pos == j:
            return lst[i]
        return lst[pos]
    return [pick(k) for k in range(len(lst))]

def distinct_items_per_group(pairs):
    from collections import defaultdict
    groups = defaultdict(set)
    for group, item in pairs:
        groups[group].add(item)
    return {g: len(items) for g, items in groups.items()}

