def kaprekar_steps(n):
    if n == 6174:
        return 0
    digits = sorted(str(n).zfill(4))
    desc = int(''.join(reversed(digits)))
    asc = int(''.join(digits))
    return 1 + kaprekar_steps(desc - asc)

