def rle_encode(lst):
    if not lst:
        return []
    result = []
    i = 0
    n = len(lst)
    while i < n:
        j = i
        while j < n and lst[j] == lst[i]:
            j += 1
        result.append([lst[i], j - i])
        i = j
    return result

