def wrap_break_long_words(text, width):
    tokens = []
    for word in text.split():
        while len(word) > width:
            tokens.append(word[:width])
            word = word[width:]
        tokens.append(word)

    lines = []
    line = []
    length = 0
    for tok in tokens:
        extra = len(tok) if not line else len(tok) + 1
        if line and length + extra > width:
            lines.append(' '.join(line))
            line = [tok]
            length = len(tok)
        else:
            line.append(tok)
            length += extra
    if line:
        lines.append(' '.join(line))
    return lines

